    if (confirmFirst) {
      const ok = await confirmAction({ title: "\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u043C\u0435\u043D\u0443?", text: `${dateText(fromKey(k), { day: "numeric", month: "long" })} \xB7 ${money(s.total)}. \u0423\u0434\u0430\u043B\u0451\u043D\u043D\u0443\u044E \u0441\u043C\u0435\u043D\u0443 \u043C\u043E\u0436\u043D\u043E \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0432 \u0440\u0430\u0437\u0434\u0435\u043B\u0435 \xAB\u0415\u0449\u0451\xBB.` });
      if (!ok) return false;
    }
